# 毕业设计 Step2: 用户故事 + 边界声明
stories = [
    {
        "story": "作为正在写文献综述的研究生, 我希望上传一批 PDF 论文后能直接用中文提问, 以便快速定位支持我论点的段落",
        "acceptance": "Given 已上传3篇PDF, When 提问'Transformer的注意力机制怎么计算', Then 返回答案且附论文名+页码",
    },
    {
        "story": "作为研究生, 我希望回答标注引用来源, 以便我能跳转原文核对, 防止 AI 幻觉误导我的论文",
        "acceptance": "Given 任意回答, When 查看引用, Then 每条引用都能在实际文档中找到对应原文",
    },
    {
        "story": "作为研究生, 我希望系统告诉我'文献里没有相关内容', 以便区分'AI不知道'和'文献没写'",
        "acceptance": "Given 提问超出文档范围, When 检索无高相关片段, Then 明确回答'知识库中未找到相关内容'而非编造",
    },
]

out_of_scope = [
    "不做多用户与权限系统(单机自用)",
    "不处理扫描件 OCR(仅支持文本型 PDF)",
    "不做实时协作与分享",
    "不支持图片/表格内容的理解(仅纯文本)",
]

lines = ["# 用户故事与边界", ""]
for i, s in enumerate(stories, 1):
    lines.append(f"## 故事 {i}\n{s['story']}\n**验收**: {s['acceptance']}")
lines.append("## 明确不做(Out of Scope)\n" + "\n".join(f"- {o}" for o in out_of_scope))
print("\n\n".join(lines))

# 毕业设计 Step3: 技术选型与理由
selections = [
    {
        "component": "LLM",
        "choice": "DeepSeek (deepseek-v4-pro)",
        "reason": "中文能力强, API 便宜(约为 GPT-4o 的 1/10), OpenAI 兼容接口国内直连",
        "alternative": "放弃 GPT-4o: 成本高且国内访问需代理, 毕业设计成本敏感",
    },
    {
        "component": "编排框架",
        "choice": "LangChain",
        "reason": "课程第2章已掌握 Chain/Retriever 抽象, RetrievalQA 开箱即用, 生态成熟",
        "alternative": "放弃裸 SDK: RAG 链路要自己拼装检索+拼prompt+解析, 重复造轮子",
    },
    {
        "component": "向量库",
        "choice": "ChromaDB",
        "reason": "pip 安装即用, 支持持久化到本地目录, 自带 metadata 过滤(存页码)",
        "alternative": "放弃 FAISS: 纯索引无元数据管理, 引用页码要另存, 增加复杂度",
    },
    {
        "component": "Embedding",
        "choice": "BGE-small-zh (sentence-transformers)",
        "reason": "中文检索效果第一梯队, 24MB 小模型本地可跑, 免 API 费用",
        "alternative": "放弃 OpenAI embedding: 按 token 收费且中文效果不如 BGE",
    },
    {
        "component": "文档解析",
        "choice": "pypdf",
        "reason": "MVP 只处理文本型 PDF, pypdf 按页提取正好满足'引用页码'需求",
        "alternative": "放弃 unstructured: 功能强但依赖重, MVP 阶段杀鸡用牛刀",
    },
]

lines = ["# 技术选型", ""]
for s in selections:
    lines.append(f"## {s['component']}: {s['choice']}")
    lines.append(f"**理由**: {s['reason']}")
    lines.append(f"**取舍**: {s['alternative']}")
print("\n\n".join(lines))
